import hashlib,json,sys,tarfile,zipfile
from pathlib import Path
p,site=map(Path,sys.argv[1:3]); results=[]
artifacts=json.loads((p/'fresh-caller-artifacts.json').read_text())
artifacts += [{'filename':'openhands_sdk-1.50.0-py3-none-any.whl','name':'openhands-sdk'}, {'filename':'openhands_tools-1.50.0-py3-none-any.whl','name':'openhands-tools'}]
for artifact in artifacts:
 f=p/artifact['filename']; sources=[]
 if f.suffix=='.whl':
  with zipfile.ZipFile(f) as z:
   sources=[(n,z.read(n)) for n in z.namelist() if n.endswith('.py')]
 else:
  with tarfile.open(f,'r:gz') as t:
   for member in t.getmembers():
    rel='/'.join(member.name.split('/')[1:])
    if rel.startswith('func_timeout/') and rel.endswith('.py'):
     sources.append((rel,t.extractfile(member).read()))
 mismatches=[]
 for rel,data in sources:
  target=site/rel
  if not target.is_file() or target.read_bytes()!=data: mismatches.append(rel)
 results.append({'name':artifact['name'],'artifact':f.name,'artifact_sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'python_sources_compared':len(sources),'mismatches':mismatches})
print(json.dumps(results,indent=2))
assert all(r['python_sources_compared']>0 and not r['mismatches'] for r in results)
